# typed: true
# frozen_string_literal: true

# Public: An authorization error generated by and attached to a
# ContentAuthorizer. See the ContentAuthorizer classes for how these get
# generated, and the ContentAuthorizationError subclasses for use-cases.
class ContentAuthorizationError

  # Public: The URL pointing to documentation that would be helpful in
  # resolving or further explaining this error.
  def documentation_url
    nil
  end

  # Public: The HTTP status code representing the error. Defaulted to 403 since
  # we are dealing primarily with authorization (not authentication) errors.
  def http_error_code
    403
  end

  # Public: A symbol representing the error. If necessary, override with more
  # specific error code in the subclasses.
  def symbolic_error_code
    :denied
  end

  # Public: Required error message. Should be a complete sentence, suitable as
  # a raw message returned via the API. So, include punctuation and capitalize
  # the first letter.
  #
  # NOTE: This is also used in model validation errors, so it should be phrased
  # in a way that supports chaining multiple comma-delimited messages together.
  #
  # Example
  #
  #   # Good
  #   error.message
  #   # => "You must have at least one verified email address to do that."
  #
  #   # Bad
  #   error.message
  #   # => "Please, verify an email address first."
  def message
    raise NotImplementedError
  end

  # Internal: An identifier for this error suitable for use in logging / instrumentation.
  def name
    self.class.to_s.split("::").pop&.underscore
  end

  # Public: The data we'll send to deliver_error.
  #
  # Returns a Hash containing the message and (optional) documentation_url
  # for this error.
  def api_error_payload
    ({}).tap do |payload|
      payload[:message] = message
      payload[:documentation_url] = documentation_url if documentation_url.present?
    end
  end
end
